def swap_case(text):
    """
    Swaps the case of every alphabetic character in a string.

    Args:
        text: The input string.

    Returns:
        The modified string with swapped cases.
    """

    swapped_text = ""
    for char in text:
        if char.isalpha():
            if char.islower():
                swapped_text += char.upper()
            else:
                swapped_text += char.lower()
        else:
            swapped_text += char

