    left, right = 0, len(values) - 1

    # Loop until the left pointer exceeds the right pointer
    while left <= right:
        # Calculate the middle index
        mid = (left + right) // 2

        # Check if the middle element is the target
        if values[mid] == target:
            return mid

        # Determine which part of the array is sorted
        if values[left] <= values[mid]:
            # Check if the target is in the left sorted part
            if values[left] <= target < values[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Check if the target is in the right sorted part
            if values[mid] < target <= values[right]:
                left = mid + 1
            else:
                right = mid - 1

    # Return -1 if the target is not found
