    left, right = 0, len(values) - 1
    while left <= right:
        mid = (left + right) // 2
        if values[mid] == target:
            return mid
        elif values[mid] >= values[left]:
            if target >= values[left] and target < values[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
