def evaluate_rpn(tokens):
    stack = []
    operators = set(['+', '-', '*', '/'])

    for token in tokens:
        if token not in operators:
            stack.append(int(token))
        else:
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            else:
                result = left / right
            stack.append(result)
    return stack[0]
