def histogram(values, bins):
    # Calculate the minimum and maximum values of the data
    min_val = min(values)
    max_val = max(values)

    # Calculate the range of the data
    range_val = max_val - min_val

    # Initialize an empty dictionary to store the histogram counts
    histogram = {}

    # Loop through each value in the data
    for value in values:
        # Calculate the bucket number for the current value
        bucket = (value - min_val) / (range_val / bins)

        # Check if the bucket number is a valid index in the histogram
        if bucket >= 0 and bucket < bins:
            # Increment the count for the current bucket
            if bucket not in histogram:
                histogram[bucket] = 1
            else:
                histogram[bucket] += 1

    return histogram
[/PYTHON]
